DIY_BOOK({"v": 1, "id": "how-to-brethe-air-isaiah-w", "title": "How To Brethe Air", "author": "Isaiah W.", "cat": "life", "hook": "Learning how to breathe matters because your body already does it automatically, yet somehow you still manage to mess it up when stressed, dizzy, or reading bad news.", "diff": 1, "mins": 1, "color": "#3b6fd4", "cover": "data:image/jpeg;base64,", "materials": ["Air", "Lungs", "Nose", "Mouth", "Blood"], "steps": [{"img": "data:image/jpeg;base64,", "text": "Get ready to inhale. Sit up straight to give your lungs plenty of room to expand.", "tip": "", "warn": "Dont hunch over, it restricts air flow."}, {"img": "data:image/jpeg;base64,", "text": "Contract your diaphragm. Let your belly soften and push outward as the dome-shaped muscle beneath your lungs flattens and moves downward.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Lift your rib cage. Allow the muscles between your ribs to pull your chest upward and outward, making space inside your torso.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": " Pull air in through your nose. Breathe in steadily so tiny nose hairs and mucus can warm, moisten, and clean the air.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Send air down the windpipe. Let the fresh air travel down your throat into your trachea, which acts like the main trunk of an upside-down tree.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Branch out into the lungs. Feel your chest fill as the air splits into smaller bronchial tubes, spreading deep into both lungs.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": " Fill the tiny air sacs. Let the air reach the millions of microscopic balloons at the ends of those tubes, called alveoli.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Swap the gases. Pause briefly at the top of your breath while oxygen passes into your blood and carbon dioxide waste leaves your blood.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Relax your muscles. Let your diaphragm rise back up and allow your rib cage to drop inward.", "tip": "", "warn": ""}, {"img": "data:image/jpeg;base64,", "text": "Push the air out. Gently exhale through your nose or mouth as your lungs deflate and push the waste air back out of your body.", "tip": "", "warn": "Some people miss this step (mainly dyspneic people), and you need to watch out for that!"}], "quiz": [{"q": "What are the mini baloons at the end of the tubes caled", "choices": ["Lungs", "Alveoli", "Idk Teach"], "answer": 1}, {"q": "What happens if you hunch over", "choices": ["PIRATE TOKEN (Not Correct)", "It helpes you breathe better", "It can restrict airflow"], "answer": 2}, {"q": "What is the gas that you breathe out", "choices": ["Methanedione", "Oxygen", "Smoke"], "answer": 0}], "updated": 1795095226733, "thumb": "data:image/jpeg;base64,"});
